// SPDX-License-Identifier: MIT
pragma solidity >=0.8.19 <0.9.0;

contract Arithmetic {
    function add(uint256 a, uint256 b) external pure returns (uint256) { return a + b; }
    function sub(uint256 a, uint256 b) external pure returns (uint256) { return a - b; }
    function mul(uint256 a, uint256 b) external pure returns (uint256) { return a * b; }
    function twice(uint256 a) external pure returns (uint256) { return a + a; }
    function chain(uint256 a, uint256 b, uint256 c) external pure returns (uint256) { return (a + b) * c; }
    function uncheckedAdd(uint256 a, uint256 b) external pure returns (uint256) {
        unchecked { return a + b; }
    }
    function narrowAdd(uint8 a, uint8 b) external pure returns (uint8) { return a + b; }
    function signedAdd(int256 a, int256 b) external pure returns (int256) { return a + b; }
}

